import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CI0evN9J.js";var i=JSON.parse(`{"title":"Use CI as the Source of Truth","description":"","frontmatter":{},"headers":[],"relativePath":"skills/contributors/use-ci-as-the-source-of-truth.md","filePath":"skills/contributors/use-ci-as-the-source-of-truth.md"}`),a={name:`skills/contributors/use-ci-as-the-source-of-truth.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="use-ci-as-the-source-of-truth" tabindex="-1">Use CI as the Source of Truth <a class="header-anchor" href="#use-ci-as-the-source-of-truth" aria-label="Permalink to “Use CI as the Source of Truth”">​</a></h1><p>Use this skill whenever you&#39;re ready to test a change in this repo — the moment you&#39;d otherwise reach for a local test run, lint, or build to check your work.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Before running any checks locally, make sure your change is on an open PR. If there isn&#39;t one yet, commit and push your branch and open one first.</li><li>Commit and push to that PR before checking whether the change works. Push first, verify second — don&#39;t spend a round of local iteration and then push once everything already looks green locally.</li><li>Treat CI as the primary feedback loop. Read the check results on the PR rather than reproducing the same test scenarios locally — CI runs the full matrix of test apps and environments this repo covers (see <a href="/guides/contributing/submitting-prs">Submitting PRs</a>), which is more than any single local run gives you.</li><li>If you know you&#39;re not done — more commits are coming, or you&#39;re still waiting on CI to tell you what&#39;s broken — mark the PR as a draft. A draft PR is still the right place to push intermediate commits and read CI feedback from; it just signals to reviewers that it isn&#39;t ready for their attention yet. Mark it ready for review only once CI is green and you consider the change complete.</li></ol><h2 id="why-push-first" tabindex="-1">Why push first <a class="header-anchor" href="#why-push-first" aria-label="Permalink to “Why push first”">​</a></h2><p>Reproducing CI&#39;s checks locally before every push duplicates work CI already does for you, and a local pass doesn&#39;t guarantee a CI pass — the two environments can differ. Pushing first and reading CI&#39;s results treats CI as authoritative: it either confirms the change works or tells you exactly what to fix next, without you needing to separately maintain a local approximation of the same signal.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};